88	
89		tx, err := dbConn.BeginTxx(ctx, nil)
90		if err != nil {
91			return echo.NewHTTPError(http.StatusInternalServerError, "failed to begin transaction: "+err.Error())
92		}
93		defer tx.Rollback()
94	
95		// 2023/11/25 10:00からの１年間の期間内であるかチェック
96		var (
97			termStartAt    = time.Date(2023, 11, 25, 1, 0, 0, 0, time.UTC)
