99			reserveStartAt = time.Unix(req.StartAt, 0)
100			reserveEndAt   = time.Unix(req.EndAt, 0)
101		)
102		if (reserveStartAt.Equal(termEndAt) || reserveStartAt.After(termEndAt)) || (reserveEndAt.Equal(termStartAt) || reserveEndAt.Before(termStartAt)) {
103			return echo.NewHTTPError(http.StatusBadRequest, "bad reservation time range")
104		}
105	
106		// 予約枠をみて、予約が可能か調べる
107		// NOTE: 並列な予約のoverbooking防止にFOR UPDATEが必要
108		var slots []*ReservationSlotModel
