		tagsByID[t.ID] = t
		tagsByName[t.Name] = t.ID
		tagList = append(tagList, &Tag{ID: t.ID, Name: t.Name})
	}
	for _, l := range lss {
		livestreamsByID[l.ID] = l
	}
	for _, lt := range lts {
		lsTags[lt.LivestreamID] = append(lsTags[lt.LivestreamID], lt.TagID)
	}
	return nil
}

